window.AUTH=window.AUTH||{};window.AUTH["21-1170"]={"d":"21-1170","id":"2022/21-1170","n":"Ciminelli v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Louis Ciminelli","date":"2022-08-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/236600/20220829154502902_Ciminelli%20Petitioner%20Brief%20-%20For%20E%20File.pdf","side":"pet","n":65},{"k":"respondent","label":"Brief of respondent Alain Kaloyeros in support of petitioner","date":"2022-08-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/236619/20220829181043374_No.%2021-1170_Brief%20for%20Respondent%20Alain%20Kaloyeros%20in%20Support%20of%20Petitioner.pdf","side":"res","n":44},{"k":"respondent","label":"Brief of respondents Steven Aiello and Joseph Gerardi in support of petitioner","date":"2022-08-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/236565/20220829124731210_Ciminelli%20v.%20US%20%208.29.22.pdfA.pdf","side":"res","n":44},{"k":"respondent","label":"Brief of respondent United States","date":"2022-10-12","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/243007/20221012202656269_21-1170bsUnitedStates%20FINAL.pdf","side":"res","n":38},{"k":"reply","label":"Reply of petitioner Louis Ciminelli","date":"2022-11-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-1170/246432/20221114161111801_Ciminelli%20Reply%20Brief.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r15_d1o2.pdf","tr":true,"items":[{"t":"case","label":"Ala. Ass’n of Realtors v. Dep’t of Health & Hum. Serv.","cite":"141 S. Ct. 2485","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2485/","sc":1,"by":{"0":"21"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"0":"18","1":"19"}},{"t":"case","label":"Boyle v. United States","cite":"556 U.S. 938","y":2009,"id":"2008/07-1309","sc":1,"sum":"The Court held that the government need not spell out a connection between criminal enterprises beyond what is apparent in the criminal activity itself.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Carpenter v. United States","cite":"484 U.S. 19","y":1987,"id":"1987/86-422","sc":1,"op":2,"ar":2,"sum":"The Court held that pre-release of a newspaper’s publication schedule qualifies as using mail and wire as an essential part of a scheme to defraud an entity of their property.","sumSrc":"Oyez","by":{"0":"passim","1":"12","2":"16","3":"16, 17, 20, 22","4":"11"}},{"t":"case","label":"Cedar Point Nursery v. Hassid","cite":"141 S. Ct. 2063","y":2021,"id":"2020/20-107","sc":1,"sum":"A California regulation granting labor organizations a “right to take access” to an agricultural employer’s property to solicit support for unionization constitutes a per se physical taking.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21","2":"30"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"op":8,"ar":2,"sum":"The Court held that State and municipal licenses in general, and Louisiana's video poker licenses in particular, do not rank as \"property,\" for purposes of federal law, in the hands of the official licensor.","sumSrc":"Oyez","by":{"0":"passim","1":"1, 15, 20, 22","2":"17, 19","3":"16, 33, 46","4":"11, 16, 24"}},{"t":"case","label":"Coll. Sav. Bank v. Fla. Prepaid Postsecondary Educ. Expense Bd.","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"sum":"The Court held that \"the federal courts are without jurisdiction to entertain this suit against an arm of the State of Florida.\" Justice Scalia concluded that \"the sovereign immunity of the State of Florida was neither validly abrogated by the Trademark Remedy Clarification Act, nor voluntarily waived by the State's activities in interstate commerce.\" Writing for the dissenting minority, Justice Stephen G. Breyer expressed the view that Congress possesses the authority to abrogate a state's sovereign immunity where necessary and proper to the exercise of a congressional power under the Constitution's Article I. Justice John Paul Stevens filed his own dissenting opinion and joined that of Justice Breyer.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Dickman v. Commissioner","cite":"465 U.S. 330","y":1984,"id":"1983/82-1041","sc":1,"sum":"The loans in question resulted in taxable gifts of the reasonable value of the use of the money lent.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 43"}},{"t":"case","label":"Durland v. United States","cite":"161 U.S. 306","y":1896,"id":"scdb/1895-139","sc":1,"sum":"The provision in Rev. Stat. § 5480, as amended by the act of March 2, 1889, c. 393, 25 Stat. 873, that “ if any person having devised or intending to devise any scheme or artifice to defraud... to be effected by either opening or intending to open correspondence or communication with any person, whether resident within or outside the United States, by means of the Post Office Establishment of the United States, or …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19, 31","1":"22","3":"40","4":"12"}},{"t":"case","label":"Elston v. Schilling","cite":"42 N.Y. 79","y":1870,"url":"https://www.courtlistener.com/c/N.Y./42/79/","by":{"0":"23"}},{"t":"case","label":"Fasulo v. United States","cite":"272 U.S. 620","y":1926,"id":"scdb/1926-024","sc":1,"sum":"A scheme for obtaining money, by means of intimidation through threats of murder and bodily harm, is not a \"scheme to defraud,\" within the meaning of Crim. Code § 215, (Rev. Stats. § 54S0,) punishing the use of the mails for the purpose of executing any \"scheme or artifice to defraud,\" etc. P. 625. 7 F. (2d) 961, reversed. FASULO v. UNITED STATES. Argument for Petitioner. CERTIORARI (269 U. S. 551) to a judgment of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 26"}},{"t":"case","label":"Fresh Pond Shopping Ctr., Inc. v. Callahan","cite":"464 U.S. 875","y":1983,"url":"https://supreme.justia.com/cases/federal/us/464/875/","sc":1,"sum":"Describing a landlord’s “power to end or terminate the physical invasion” of a tenant as the power to “restor[e] control of his property”.","sumSrc":"brief:0","by":{"0":"21"}},{"t":"case","label":"Hammerschmidt v. United States","cite":"265 U.S. 182","y":1924,"id":"scdb/1923-145","sc":1,"sum":"1. Section 37 of the Criminal Code (Rev. Stats., § 540) punishing conspiracy to defraud.the United StAtes in any manner or fok any purpose,\" does not embrace a conspiracy to defeat the pur-pose of the Selective Draft Act by inducing persons-to refuse to register under it.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"22","4":"10"}},{"t":"case","label":"Johnson v. United States","cite":"576 U.S. 591","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"41, 47"}},{"t":"case","label":"Jones v. United States","cite":"529 U.S. 848","y":2000,"id":"1999/99-5739","sc":1,"sum":"Delivered by Justice Ruth Bader Ginsburg, the Court held that an owner-occupied residence not used for any commercial purpose does not qualify as property \"used in\" commerce or commerce-affecting activity, such that arson of such a dwelling is not subject to federal prosecution under section 844(i).","sumSrc":"Oyez","by":{"0":"41","1":"20"}},{"t":"case","label":"Kansas v. Garcia","cite":"140 S. Ct. 791","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"sum":"The Court held that Baroni and Kelly, who executed the New Jersey “Bridgegate” political retribution scheme against Fort Lee’s mayor, did not violate the federal-program fraud or wire fraud laws because they did not aim to obtain money or property from the federal Port Authority.","sumSrc":"Oyez","by":{"0":"passim","1":"1, 13, 20, 33","2":"3, 16, 17, 29","3":"16, 32","4":"10, 11, 24"}},{"t":"case","label":"Loretto v. Teleprompter Manhattan CATV Corp.","cite":"458 U.S. 419","y":1982,"id":"1981/81-244","sc":1,"sum":"The New York statute works a taking of a portion of appellant's property for which she is entitled to just compensation under the Fifth Amendment, as made applicable to the States by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 23"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"46, 47","1":"20","4":"16"}},{"t":"case","label":"McKeon v. Bisbee","cite":"9 Cal. 137","y":1858,"url":"https://www.courtlistener.com/c/Cal./9/137/","by":{"0":"20"}},{"t":"case","label":"McNally v. United States","cite":"483 U.S. 350","y":1987,"id":"1986/86-234","sc":1,"op":7,"ar":6,"sum":"The jury charge permitted a conviction for conduct not within the reach of § 1341.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"17, 33","3":"16, 46","4":"10, 11, 20"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"op":1,"ar":3,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"0":"19, 38, 39","1":"22","3":"15, 17, 18, 21, 42, 44","4":"7, 9, 10, 17"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"18","1":"34"}},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"op":1,"sum":"The Court held that the law's plain language criminalized the smuggling scheme in this case. The common-law revenue rule did not bar the prosecution of the scheme, because no common-law case as of 1952 clearly established that the rule barred the U.S. from prosecuting a fraudulent scheme to evade foreign taxes.","sumSrc":"Oyez","by":{"0":"19, 20, 32","1":"22","3":"11, 16, 17, 32, 33"}},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) authorizes the Environmental Protection Agency (EPA) to use data submitted by an applicant for registration of a covered product (hereinafter pesticide) in evaluating the application of a subsequent applicant, and to disclose publicly some of the submitted data. Under the dataconsideration provisions of § 3, as amended in 1978, applicants now are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Salman v. United States","cite":"137 S. Ct. 420","y":2016,"id":"2016/15-628","sc":1,"sum":"The Court held that evidence of a close family relationship sufficient is to sustain a conviction for insider trading.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Scheidler v. Nat’l Org. for Women, Inc.","cite":"537 U.S. 393","y":2003,"id":"2002/01-1118","sc":1,"sum":"The Court held that abortion opponents did not commit extortion because they did not \"obtain\" property from the abortion supporters as required by the Hobbs Act. The Court further held that is first holding renders insufficient the other bases or predicate acts of racketeering supporting the jury's conclusion that the abortion opponents violated RICO.","sumSrc":"Oyez","by":{"0":"33","2":"passim"}},{"t":"case","label":"Sekhar v. United States","cite":"570 U.S. 729","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"0":"32, 33","2":"passim"}},{"t":"case","label":"Shaw v. United States","cite":"137 S. Ct. 462","y":2016,"id":"2016/15-5991","sc":1,"ar":5,"sum":"The Court determined that, to convict a defendant of defrauding a financial institution under the Bank Fraud Act of 1984, the government does not need to prove that the target of the deception was a bank.","sumSrc":"Oyez","by":{"0":"28, 30","3":"21, 40","4":"11, 12"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"op":1,"ar":1,"sum":"The Court held that the former CEO of Enron received a fair trial before an impartial jury, and that the federal law that makes it a crime to deprive someone of a fair and honest trial only applies to bribery and kickback schemes.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"1, 18, 19, 40","3":"16, 46, 47","4":"20, 21"}},{"t":"case","label":"Smith v. Shaughnessy","cite":"318 U.S. 176","y":1943,"id":"scdb/1942-122","sc":1,"sum":"that the remainder interest, less the value of the grantor's reversionary interest, was subject to the gift tax imposed by §§ 501, 506 of the Revenue Act of 1932.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"United States v. Biaggi","cite":"909 F.2d 662","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/909/662/","by":{"0":"17","1":"28, 29, 30"}},{"t":"case","label":"United States v. Binday","cite":"804 F.3d 558","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/804/558/","op":1,"sum":"Noting that “commission payments” “ ‘were the ‘money or property’ implicated by the scheme’ ”.","sumSrc":"brief:3","by":{"0":"passim","1":"1, 8, 31","2":"34","3":"24, 25, 26, 27"}},{"t":"case","label":"United States v. Craft","cite":"535 U.S. 274","y":2002,"id":"2001/00-1831","sc":1,"sum":"The Court held that each tenant possesses individual rights in the estate sufficient to constitute \"property\" or \"rights to property\" for the purposes of the lien.","sumSrc":"Oyez","by":{"0":"27, 42"}},{"t":"case","label":"United States v. D’Amato","cite":"39 F.3d 1249","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/39/1249/","by":{"0":"40"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33, 48"}},{"t":"case","label":"United States v. Fagan","cite":"821 F.2d 1002","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/821/1002/","by":{"0":"39","1":"passim"}},{"t":"case","label":"United States v. Finazzo","cite":"850 F.3d 94","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/850/94/","ar":1,"by":{"0":"39","1":"1, 8, 30, 31, 33","2":"3, 26, 27, 41","3":"passim","4":"13, 14"}},{"t":"case","label":"United States v. Gen. Motors Corp.","cite":"323 U.S. 373","y":1945,"id":"scdb/1944-056","sc":1,"sum":"In proceedings to determine the measure of just compensation required by the Fifth Amendment to be made to a leaseholder where the Government has taken, for part of the unexpired term of a lease, the occupancy of a warehouse which was equipped for and used in the leaseholder's business, held:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Johnson","cite":"945 F.3d 606","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/945/606/","sum":"Describing that inquiry as part of the intent-to-defraud element.","sumSrc":"brief:3","by":{"0":"38, 40","3":"30, 31"}},{"t":"case","label":"United States v. Kerkman","cite":"866 F.2d 877","y":1989,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/866/877/","by":{"0":"17","1":"28, 29"}},{"t":"case","label":"United States v. Little","cite":"889 F.2d 1367","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/889/1367/","op":1,"sum":"Stating that “concealing economic information constitutes a property loss”.","sumSrc":"brief:2","by":{"0":"17","1":"28, 29","2":"28"}},{"t":"case","label":"United States v. Miller","cite":"953 F.3d 1095","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/953/1095/","by":{"0":"28, 29"}},{"t":"case","label":"United States v. Novak","cite":"443 F.3d 150","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/443/150/","by":{"0":"45"}},{"t":"case","label":"United States v. Ochs","cite":"842 F.2d 515","y":1988,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/842/515/","by":{"0":"37","1":"30"}},{"t":"case","label":"United States v. Regent Off. Supply Co.","cite":"421 F.2d 1174","y":1970,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/421/1174/","by":{"0":"40, 44, 45"}},{"t":"case","label":"United States v. Rowe","cite":"56 F.2d 747","y":1932,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/56/747/","by":{"0":"17","3":"21, 40","4":"12"}},{"t":"case","label":"United States v. Sadler","cite":"750 F.3d 585","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/750/585/","op":2,"sum":"Holding that the fraud statutes do not “stretch ... to cover the right to accurate information before making an otherwise fair exchange.”.","sumSrc":"brief:2","by":{"0":"35, 36","2":"39"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"sum":"Splitting 5 to 4, the Court affirmed the Seventh Circuit, answering that \"proceeds\" refers to \"net income\" or profits and not to \"gross income.\" Because the statute nowhere defines the term \"proceeds\", the plurality applied the so-called rule of lenity which requires such ambiguous statutes to be interpreted in favor of defendants.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"United States v. Schwartz","cite":"924 F.2d 410","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/924/410/","by":{"0":"46"}},{"t":"case","label":"United States v. Shellef","cite":"507 F.3d 82","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/507/82/","by":{"0":"8, 44, 45, 46"}},{"t":"case","label":"United States v. Shyres","cite":"898 F.2d 647","y":1990,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/898/647/","by":{"0":"17","1":"28, 29"}},{"t":"case","label":"United States v. Starr","cite":"816 F.2d 94","y":1987,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/816/94/","by":{"0":"45","4":"12"}},{"t":"case","label":"United States v. Taylor","cite":"142 S. Ct. 2015","y":2022,"id":"2021/20-1459","sc":1,"sum":"Attempted Hobbs Act robbery does not qualify as a “crime of violence” under 18 U. S. C. §924(c)(3)(A) because no element of the offense requires proof that the defendant used, attempted to use, or threatened to use force.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"11, 41"}},{"t":"case","label":"United States v. Wallach","cite":"935 F.2d 445","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/935/445/","op":3,"ar":3,"by":{"0":"passim","1":"passim","2":"28, 41"}},{"t":"case","label":"United States v. Walters","cite":"997 F.2d 1219","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/997/1219/","by":{"0":"31","2":"18"}},{"t":"case","label":"United States v. Yates","cite":"16 F.4th 256","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/16/256/","by":{"0":"37","1":"30"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"0":"5"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","stext":{"head":"§1341. Frauds and swindles","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, or to sell, dispose of, loan, exchange, alter, give away, distribute, supply, or furnish or procure for unlawful use any counterfeit or spurious coin, obligation, security, or other article, or anything represented to be or intimated or held out to be such counterfeit or spurious article, for the purpose of executing such scheme or artifice or attempting so to do, places in any post office or authorized depository for mail matter, any matter or thing whatever to be sent or delivered by the Postal Service, or deposits or causes to be deposited any matter or thing whatever to be sent or delivered by any private or commercial interstate carrier, or takes or receives therefrom, any such matter or thing, or knowingly causes to be delivered by mail or such carrier according to the direction thereon, or at the place at which it is directed to be delivered by the person to whom it is addressed, any such matter or thing, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1341?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1341. Frauds and swindles","tname":"Crimes and Criminal Procedure","by":{"0":"31","1":"passim","2":"3, 15, 16","3":"15"}},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","stext":{"head":"§1343. Fraud by wire, radio, or television","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, transmits or causes to be transmitted by means of wire, radio, or television communication in interstate or foreign commerce, any writings, signs, signals, pictures, or sounds for the purpose of executing such scheme or artifice, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1343?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1343. Fraud by wire, radio, or television","tname":"Crimes and Criminal Procedure","by":{"0":"2, 5, 31","1":"passim","2":"3, 6, 15, 16","3":"passim"}},{"t":"usc","label":"18 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/18/1346","stext":{"head":"§1346. Definition of \"scheme or artifice to defraud\"","paras":[[0,"For the purposes of this chapter, the term \"scheme or artifice to defraud\" includes a scheme or artifice to deprive another of the intangible right of honest services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1346?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§1346. Definition of \"scheme or artifice to defraud\"","tname":"Crimes and Criminal Procedure","by":{"0":"10, 14, 35, 36","1":"passim","3":"46"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","stext":{"head":"§1349. Attempt and conspiracy","paras":[[0,"Any person who attempts or conspires to commit any offense under this chapter shall be subject to the same penalties as those prescribed for the offense, the commission of which was the object of the attempt or conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1349?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1349. Attempt and conspiracy","tname":"Crimes and Criminal Procedure","by":{"0":"4","1":"5","2":"6","3":"2, 8"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","stext":{"head":"§1951. Interference with commerce by threats or violence","paras":[[0,"(a) Whoever in any way or degree obstructs, delays, or affects commerce or the movement of any article or commodity in commerce, by robbery or extortion or attempts or conspires so to do, or commits or threatens physical violence to any person or property in furtherance of a plan or purpose to do anything in violation of this section shall be fined under this title or imprisoned not more than twenty years, or both."],[0,"(b) As used in this section—"],[1,"(1) The term \"robbery\" means the unlawful taking or obtaining of personal property from the person or in the presence of another, against his will, by means of actual or threatened force, or violence, or fear of injury, immediate or future, to his person or property, or property in his custody or possession, or the person or property of a relative or member of his family or of anyone in his company at the time of the taking or obtaining."],[1,"(2) The term \"extortion\" means the obtaining of property from another, with his consent, induced by wrongful use of actual or threatened force, violence, or fear, or under color of official right."],[1,"(3) The term \"commerce\" means commerce within the District of Columbia, or any Territory or Possession of the United States; all commerce between any point in a State, Territory, Possession, or the District of Columbia and any point outside thereof; all commerce between points within the same State through any place outside such State; and all other commerce over which the United States has jurisdiction."],[0,"(c) This section shall not be construed to repeal, modify or affect section 17 of Title 15, sections 52, 101–115, 151–166 of Title 29 or sections 151–188 of Title 45."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1951?type=usc&year=mostrecent&link-type=html"},"head":"§1951. Interference with commerce by threats or violence","tname":"Crimes and Criminal Procedure","by":{"0":"32","2":"19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"case","label":"Ingber v. Enzor","cite":"841 F.2d 450","y":1988,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/841/450/","by":{"1":"30"}},{"t":"case","label":"Penturelli v. Spector, Cohen, Gadon & Rosen","cite":"779 F.2d 160","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/779/160/","by":{"1":"23"}},{"t":"case","label":"Ranke v. United States","cite":"873 F.2d 1033","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/873/1033/","by":{"1":"28, 29"}},{"t":"case","label":"Shushan v. United States","cite":"117 F.2d 110","y":1941,"url":"https://www.courtlistener.com/c/F.2d/117/110/","by":{"1":"14"}},{"t":"case","label":"Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"sum":"The Court held that the district court has maritime jurisdiction when the incident in question represents a potential hazard to maritime commerce and bears a substantial relationship to maritime activity.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Sorich v. United States","cite":"555 U.S. 1204","y":2009,"url":"https://supreme.justia.com/cases/federal/us/555/1204/","sc":1,"by":{"1":"15, 32"}},{"t":"case","label":"United States v. Bein","cite":"728 F.2d 107","y":1984,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/728/107/","by":{"1":"23"}},{"t":"case","label":"United States v. Bush","cite":"522 F.2d 641","y":1975,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/522/641/","by":{"1":"24"}},{"t":"case","label":"United States v. Cauble","cite":"706 F.2d 1322","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/706/1322/","by":{"1":"23"}},{"t":"case","label":"United States v. Conner","cite":"752 F.2d 566","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/752/566/","by":{"1":"23-24"}},{"t":"case","label":"United States v. George","cite":"477 F.2d 508","y":1973,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/477/508/","by":{"1":"23, 24, 28"}},{"t":"case","label":"United States v. Iaciofano","cite":"734 F.2d 87","y":1984,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/734/87/","by":{"1":"23"}},{"t":"case","label":"United States v. Johnson","cite":"496 F.2d 1131","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/496/1131/","by":{"1":"23"}},{"t":"case","label":"United States v. Lebedev","cite":"932 F.3d 40","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/932/40/","op":1,"by":{"1":"8, 31, 33","2":"34"}},{"t":"case","label":"United States v. Rico Indus.","cite":"854 F.2d 710","y":1988,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/854/710/","by":{"1":"27"}},{"t":"case","label":"United States v. Ron Pair Enters.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"United States v. Von Barta","cite":"635 F.2d 999","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/635/999/","by":{"1":"23, 24"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"sum":"An affirmative act of inducement by a public official, such as a demand, is not an element of the offense of extortion \"under color of official right\" prohibited by the Hobbs Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Gamble v. United States","cite":"139 S. Ct. 1960","y":2019,"id":"2018/17-646","sc":1,"sum":"The dual sovereignty doctrine—under which two offenses are not the “same offence” for double jeopardy purposes if prosecuted by separate sovereigns—is upheld.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"1"}},{"t":"case","label":"Honeycutt v. United States","cite":"137 S. Ct. 1626","y":2017,"id":"2016/16-142","sc":1,"sum":"The Court determined that the federal forfeiture statute does not require joint and several liability among co-conspirators for any reasonably foreseeable proceeds of conspiracy.","sumSrc":"Oyez","by":{"2":"23, 24"}},{"t":"case","label":"Kungys v. United States","cite":"485 U.S. 759","y":1988,"id":"1986/86-228","sc":1,"sum":"The judgment of the Court of Appeals is reversed, and the case is remanded. 793 F. 2d 516, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"ar":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"2":"17","3":"17, 22, 47, 48","4":"12"}},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"sum":"The Court held that a conviction under 26 U.S.C. § 7212(a) for corruptly endeavoring to obstruct or impede the due administration of the tax laws requires proof that the defendant acted with knowledge of a pending Internal Revenue Service action.","sumSrc":"Oyez","by":{"2":"40","4":"16"}},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"sum":"1. A criminal intent is an essential element of an offense under 18 U. S. C. § 641, which provides that \"whoever embezzles, steals, purloins, or knowingly converts\" property -of the United States is punishable by fine and imprisonment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Nichols v. United States","cite":"578 U.S. 104","y":2016,"id":"2015/15-5238","sc":1,"sum":"The Court determined that the Sexual Offender Registration and Notification Act does not require a sex offender who is moving to a country outside of U.S. jurisdiction to update his residence with the sexual offender registry.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Porcelli v. United States","cite":"404 F.3d 157","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/404/157/","by":{"2":"26"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"142 S. Ct. 1783","y":2022,"id":"2021/21-309","sc":1,"sum":"Airplane cargo loaders and ramp supervisors who, like petitioner Saxon, frequently load and unload airplane cargo belong to a “class of workers engaged in foreign or interstate commerce” exempt from the Federal Arbitration Act’s coverage.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"33"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"sum":"An offense constitutes \"burglary\" under §924(e) if, regardless of its exact definition or label, it has the basic elements of a \"generic\" burglary-i. e., an unlawful or unprivileged entry into, or remaining in, a building or other structure, with intent to commit a crime-or if the charging paper and jury instructions actually required the jury to find all the elements of generic burglary in order to convict the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"United States v. Clapps","cite":"732 F.2d 1148","y":1984,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/732/1148/","by":{"2":"16, 17"}},{"t":"case","label":"vii United States v. Gatto","cite":"986 F.3d 104","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/986/104/","by":{"2":"3, 39"}},{"t":"case","label":"United States v. Hedaithy","cite":"392 F.3d 580","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/392/580/","by":{"2":"27"}},{"t":"case","label":"United States v. Nardello","cite":"393 U.S. 286","y":1969,"id":"1968/51","sc":1,"sum":"In light of the congressional purpose to assist local law enforcement officials in combating interstate activities of organized crime which violate state laws, and not merely to eliminate only those acts which a State has denominated extortion, the extortionate acts for which appellees were indicted, which were prohibited by Pennsylvania law, fall within the generic term \"extortion\" as used in 18 U. S. C. § 1952. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"United States v. Sekhar","cite":"683 F.3d 436","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/683/436/","by":{"2":"22"}},{"t":"case","label":"United States v. Takhalov","cite":"827 F.3d 1307","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/827/1307/","by":{"2":"39"}},{"t":"case","label":"United States v. Weimert","cite":"819 F.3d 351","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/819/351/","by":{"2":"38"}},{"t":"case","label":"Wilson v. Ward Lumber","cite":"67 F. 674","y":1895,"court":"C.C.E.D. Mo.","url":"https://www.courtlistener.com/c/F./67/674/","by":{"2":"31"}},{"t":"case","label":"viii Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"2":"1"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","by":{"2":"32"}},{"t":"usc","label":"20 U.S.C. § 4302","url":"https://www.law.cornell.edu/uscode/text/20/4302","by":{"2":"32"}},{"t":"usc","label":"21 U.S.C. § 853","url":"https://www.law.cornell.edu/uscode/text/21/853","by":{"2":"23"}},{"t":"case","label":"Buchanan v. Warley","cite":"245 U.S. 60","y":1917,"id":"1900-1940/245us60","sc":1,"sum":"The Court reversed the Kentucky Court of Appeals and ruled that the ordinance was unconstitutional.","sumSrc":"Oyez","by":{"3":"25"}},{"t":"case","label":"Chiarella v. United States","cite":"445 U.S. 222","y":1980,"id":"1979/78-1202","sc":1,"op":1,"ar":5,"sum":"A duty to disclose information arises if there is a relationship of trust and confidence between parties to the transaction. Chiarella had no such duty. He was not a corporate insider in the acquiring corporation and he did not receive confidential information from the target company.","sumSrc":"Oyez","by":{"3":"17, 20, 47","4":"5"}},{"t":"case","label":"Janes v. Trustees of Mercer Univ.","cite":"17 Ga. 515","y":1855,"url":"https://www.courtlistener.com/c/Ga./17/515/","by":{"3":"19"}},{"t":"case","label":"J.I. Case Threshing Mach. Co. v. Webb","cite":"181 S.W. 853","y":1915,"court":"Tex. Civ. App.","url":"https://www.courtlistener.com/c/S.W./181/853/","ar":1,"by":{"3":"19"}},{"t":"case","label":"Junius Constr. Co. v. Cohen","cite":"178 N.E. 672","y":1931,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./178/672/","by":{"3":"18"}},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"3":"31","4":"5, 6"}},{"t":"case","label":"Schmuck v. United States","cite":"489 U.S. 705","y":1989,"id":"1988/87-6431","sc":1,"sum":"Petitioner used-car distributor was charged with multiple counts of mail fraud. The indictment alleged that he purchased used cars, rolled back their odometers, and sold them to Wisconsin retail dealers at prices artificially inflated by the low-mileage readings, and that the unwitting dealers, relying on the altered readings, resold the cars to customers at inflated prices, consummating the transactions by mailing …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"29"}},{"t":"case","label":"State v. Mills","cite":"17 Me. 211","y":1840,"url":"https://www.courtlistener.com/c/Me./17/211/","by":{"3":"19","4":"8, 9"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"44","4":"18"}},{"t":"case","label":"United States v. Jabar","cite":"19 F.4th 66","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/19/66/","sum":"Observing that the “right to control theory” “turns on the materiality of the misrepresentations”.","sumSrc":"brief:3","by":{"3":"30"}},{"t":"case","label":"United States v. Leahy","cite":"464 F.3d 773","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/464/773/","sum":"Rejecting challenge to sufficiency of indictment where defendants falsely represented critical qualifications in order to obtain government contracts, despite defendants’ argument that the victim received “a service worth every dime in the contracts”.","sumSrc":"brief:3","by":{"3":"23"}},{"t":"case","label":"United States v. New S. Farm & Home Co.","cite":"241 U.S. 64","y":1916,"id":"scdb/1915-212","sc":1,"sum":"While the fraudulent advertisements covered by the provisions of § 215, Criminal Code, prohibiting using the mails for advertisements, may not include those which merely puff the article to be sold by exaggerating its qualities, it does prohibit using the mails for fraudulent statements assigning to such article qualities which it does not possess.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"29, 45"}},{"t":"case","label":"United States v. Maxwell","cite":"579 F.3d 1282","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/579/1282/","by":{"3":"20"}},{"t":"case","label":"United States v. Mittelstaedt","cite":"31 F.3d 1208","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/31/1208/","sum":"Holding that “lack of information that might have an impact on the decision regarding where government money is spent, without more, is not a tangible harm”.","sumSrc":"brief:3","by":{"3":"28"}},{"t":"case","label":"United States v. Sampson","cite":"371 U.S. 75","y":1962,"id":"1962/69","sc":1,"sum":"The judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"40","4":"12"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"3":"44"}},{"t":"case","label":"United States v. Viloski","cite":"557 Fed. Appx. 28","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./557/28/","op":1,"sum":"Finding jury instruction consistent with theory because it did not define property that way.","sumSrc":"brief:3","by":{"3":"28"}},{"t":"case","label":"Universal Health Servs., Inc. v. United States","cite":"579 U.S. 176","y":2016,"id":"2015/15-7","sc":1,"ar":1,"sum":"The Court held that the implied certification test could be a valid basis for False Claims Act liability, and the conditions of payment with which the defendant allegedly failed to comply did not need to be explicitly stated.","sumSrc":"Oyez","by":{"3":"13, 18, 30, 43, 44","4":"17, 22"}},{"t":"case","label":"Washington Post Co. v. Sorrells","cite":"68 S.E. 337","y":1910,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E./68/337/","by":{"3":"19"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","by":{"3":"15"}},{"t":"case","label":"Atl. Delaine Co. v. James","cite":"94 U.S. 207","y":1876,"id":"scdb/1876-130","sc":1,"by":{"4":"8"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"4"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"4":"4"}},{"t":"case","label":"Dunn v. United States","cite":"442 U.S. 100","y":1979,"id":"1978/77-6949","sc":1,"ar":2,"sum":"Petitioner's testimony before a grand jury in June 1976 implicated one Musgrave in various drug-related offenses, and an indictment of Musgrave followed. On September 30, 1976, petitioner recanted his testimony in an oral statement made under oath in the office of Musgrave's attorney. Musgrave then moved to dismiss his indictment, alleging that it was based on perjured testimony. At an evidentiary hearing on this …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"5"}},{"t":"case","label":"Dura Pharms., Inc. v. Broudo","cite":"544 U.S. 336","y":2005,"id":"2004/03-932","sc":1,"sum":"The Court held that an inflated purchase price did not by itself prove \"loss causation.\" At most, an inflated purchase price suggested that misrepresentation \"touched upon\" a later economic loss, but did not necessarily cause it.","sumSrc":"Oyez","by":{"4":"7"}},{"t":"case","label":"Junius Constr. Corp. v. Cohen","cite":"257 N.Y. 393","y":1931,"url":"https://www.courtlistener.com/c/N.Y./257/393/","by":{"4":"17"}},{"t":"case","label":"Mauro v. Raymark Indus., Inc.","cite":"561 A.2d 257","y":1989,"court":"N.J.","url":"https://www.courtlistener.com/c/A.2d/561/257/","by":{"4":"13"}},{"t":"case","label":"McCormick v. United States","cite":"500 U.S. 257","y":1991,"id":"1990/89-1918","sc":1,"op":1,"ar":1,"sum":"Petitioner McCormick, a member of the West Virginia House of Delegates in 1984, was a leading advocate of a legislative program allowing foreign medical school graduates to practice under temporary permits while studying for the state licensing exams. Some doctors practiced for years under the program, as they repeatedly failed those exams. He sponsored a bill, sought by an organization of those doctors, extending …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"5"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"4":"5"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"4":"4"}},{"t":"case","label":"One-O-One Enters. v. Caruso","cite":"848 F.2d 1283","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/848/1283/","by":{"4":"19, 20"}},{"t":"case","label":"People v. Cook","cite":"8 N.Y. 67","y":1853,"url":"https://www.courtlistener.com/c/N.Y./8/67/","by":{"4":"7"}},{"t":"case","label":"S. Dev. Co. of Nev. v. Silva","cite":"125 U.S. 247","y":1888,"id":"scdb/1887-181","sc":1,"sum":"The general rule that when the answer of the defendant in a cause in equity is direct, positive, and unequivocal in its denial of the allegations in the bill, and an answer on.oath is not waived, the complainant will not be entitled +o a decree unless these denials are disproved by evidence of greater weight than the testimony of one witness, or by that of one witness with corroborating circumstances, applies when …","sumSrc":"Headnote (U.S. Reports)","by":{"4":"8"}},{"t":"case","label":"Sonnesyn v. Akin","cite":"104 N.W. 1026","y":1905,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W./104/1026/","by":{"4":"7"}},{"t":"case","label":"State v. Casperson","cite":"262 P. 294","y":1927,"court":"Utah","url":"https://www.courtlistener.com/c/P./262/294/","by":{"4":"9"}},{"t":"case","label":"State v. Palmer","cite":"32 P. 29","y":1893,"court":"Kan.","url":"https://www.courtlistener.com/c/P./32/29/","by":{"4":"9"}},{"t":"case","label":"Stirone v. United States","cite":"361 U.S. 212","y":1960,"id":"1959/35","sc":1,"sum":"The conviction is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"5"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"13"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"4":"4"}},{"t":"case","label":"United States v. Lindsey","cite":"850 F.3d 1009","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/850/1009/","by":{"4":"18"}},{"t":"case","label":"United States v. Palin","cite":"874 F.3d 418","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/418/","by":{"4":"18"}},{"t":"case","label":"Va. Bankshares, Inc. v. Sandberg","cite":"501 U.S. 1083","y":1991,"id":"1990/89-1448","sc":1,"sum":"Respectively. Terms like \"high value,\" in a commercial context, are reasonably understood to rest on a factual basis, and so could be shown to be misleading by garden-variety evidence. Furthermore, they can be materially misleading even if other information is available in the statement upon which an expert could deduce that they are false. A proxy statement should inform, not challenge the reader's critical wits.","sumSrc":"Oyez","by":{"4":"19"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"17"}}]};